class CacheNode:
    def __init__(self, key: int, value: int) -> None:
        self.key = key
        self.value = value
        self.prev = self
        self.next = self


class LRUCache:
    def __init__(self, capacity: int) -> None:
        self.capacity = capacity
        self.nodes: dict[int, CacheNode] = {}
        # A dummy node in a circular list: right after it comes the most
        # recently used node, and right before it the least recently used one.
        self.head = CacheNode(0, 0)

    def unlink(self, node: CacheNode) -> None:
        node.prev.next = node.next
        node.next.prev = node.prev

    def push_front(self, node: CacheNode) -> None:
        node.prev = self.head
        node.next = self.head.next
        self.head.next.prev = node
        self.head.next = node

    def get(self, key: int) -> int:
        node = self.nodes.get(key)
        if node is None:
            return -1
        self.unlink(node)
        self.push_front(node)
        return node.value

    def put(self, key: int, value: int) -> None:
        node = self.nodes.get(key)
        if node is not None:
            node.value = value
            self.unlink(node)
        else:
            if len(self.nodes) == self.capacity:
                oldest = self.head.prev
                self.unlink(oldest)
                del self.nodes[oldest.key]
            node = CacheNode(key, value)
            self.nodes[key] = node
        self.push_front(node)


