#include <iostream>
#include <string>
#include <unordered_map>

struct CacheNode {
    int key;
    int value;
    CacheNode* prev;
    CacheNode* next;

    CacheNode(int key, int value) : key(key), value(value), prev(this), next(this) {}
};

class LRUCache {
public:
    explicit LRUCache(int capacity) : capacity_(capacity) {}

    int get(int key) {
        auto it = nodes_.find(key);
        if (it == nodes_.end()) {
            return -1;
        }
        CacheNode* node = it->second;
        unlink(node);
        pushFront(node);
        return node->value;
    }

    void put(int key, int value) {
        auto it = nodes_.find(key);
        CacheNode* node;
        if (it != nodes_.end()) {
            node = it->second;
            node->value = value;
            unlink(node);
        } else {
            if (static_cast<int>(nodes_.size()) == capacity_) {
                CacheNode* oldest = head_.prev;
                unlink(oldest);
                nodes_.erase(oldest->key);
                delete oldest;
            }
            node = new CacheNode(key, value);
            nodes_[key] = node;
        }
        pushFront(node);
    }

private:
    static void unlink(CacheNode* node) {
        node->prev->next = node->next;
        node->next->prev = node->prev;
    }

    void pushFront(CacheNode* node) {
        node->prev = &head_;
        node->next = head_.next;
        head_.next->prev = node;
        head_.next = node;
    }

    int capacity_;
    std::unordered_map<int, CacheNode*> nodes_;
    // A dummy node in a circular list: right after it comes the most
    // recently used node, and right before it the least recently used one.
    CacheNode head_{0, 0};
};

