    int value;
    CacheNode prev = this;
    CacheNode next = this;

    CacheNode(int key, int value) {
        this.key = key;
        this.value = value;
    }
}

class LRUCache {
    private final int capacity;
    private final Map<Integer, CacheNode> nodes = new HashMap<>();
    // A dummy node in a circular list: right after it comes the most
    // recently used node, and right before it the least recently used one.
    private final CacheNode head = new CacheNode(0, 0);

    LRUCache(int capacity) {
        this.capacity = capacity;
    }

    int get(int key) {
        CacheNode node = nodes.get(key);
        if (node == null) {
            return -1;
        }
        unlink(node);
        pushFront(node);
        return node.value;
    }

    void put(int key, int value) {
        CacheNode node = nodes.get(key);
        if (node != null) {
            node.value = value;
            unlink(node);
        } else {
            if (nodes.size() == capacity) {
                CacheNode oldest = head.prev;
                unlink(oldest);
                nodes.remove(oldest.key);
            }
            node = new CacheNode(key, value);
            nodes.put(key, node);
        }
        pushFront(node);
    }

    private void unlink(CacheNode node) {
        node.prev.next = node.next;
        node.next.prev = node.prev;
    }

    private void pushFront(CacheNode node) {
        node.prev = head;
        node.next = head.next;
        head.next.prev = node;
        head.next = node;
    }
}

