package main

import "fmt"

// CacheNode is one key-value pair in a doubly linked list.
type CacheNode struct {
	key, value int
	prev, next *CacheNode
}

// LRUCache keeps the most recently used key-value pairs.
type LRUCache struct {
	capacity int
	nodes    map[int]*CacheNode
	// A dummy node in a circular list: right after it comes the most
	// recently used node, and right before it the least recently used one.
	head *CacheNode
}

func newLRUCache(capacity int) *LRUCache {
	head := &CacheNode{}
	head.prev, head.next = head, head
	return &LRUCache{capacity: capacity, nodes: map[int]*CacheNode{}, head: head}
}

func (c *LRUCache) unlink(node *CacheNode) {
	node.prev.next = node.next
	node.next.prev = node.prev
}

func (c *LRUCache) pushFront(node *CacheNode) {
	node.prev = c.head
	node.next = c.head.next
	c.head.next.prev = node
	c.head.next = node
}

func (c *LRUCache) get(key int) int {
	node, ok := c.nodes[key]
	if !ok {
		return -1
	}
	c.unlink(node)
	c.pushFront(node)
	return node.value
}

func (c *LRUCache) put(key, value int) {
	node, ok := c.nodes[key]
	if ok {
		node.value = value
		c.unlink(node)
	} else {
		if len(c.nodes) == c.capacity {
			oldest := c.head.prev
			c.unlink(oldest)
			delete(c.nodes, oldest.key)
		}
		node = &CacheNode{key: key, value: value}
		c.nodes[key] = node
	}
	c.pushFront(node)
}

func main() {
	var capacity, q int
	fmt.Scan(&capacity, &q)
	cache := newLRUCache(capacity)
	for i := 0; i < q; i++ {
		var op string
		var key, value int
		fmt.Scan(&op, &key)
		if op == "get" {
			fmt.Println(cache.get(key))
		} else {
			fmt.Scan(&value)
			cache.put(key, value)
		}
	}
}

